INSERT INTO app_agent_approval (
    task_id, step_id, approval_type, status, requested_by, reason,
    target_summary, parameter_hash, expires_at
) VALUES (
    #{taskId}, #{stepId}, #{approvalType}, #{status}, #{requestedBy}, #{reason},
    #{targetSummary}, #{parameterHash}, #{expiresAt}
)

