DELETE FROM app_agent_step
WHERE plan_id = #{planId}
  AND status IN ('PENDING', 'BLOCKED', 'READY', 'WAITING_APPROVAL')

mapper.update:
UPDATE app_agent_step
SET lease_until = #{leaseUntil}, updated_at = CURRENT_TIMESTAMP
WHERE id = #{stepId} AND status = 'RUNNING' AND lease_owner = #{owner}

