INSERT INTO app_agent_usage_ledger (
    task_id, step_id, tenant_key, idempotency_key, tool_name, attempt,
    token_usage, cost_amount, status
) VALUES (
    #{taskId}, #{stepId}, #{tenantKey}, #{idempotencyKey}, #{toolName}, #{attempt},
    #{tokenUsage}, #{costAmount}, #{status}
)
ON DUPLICATE KEY UPDATE idempotency_key = idempotency_key

mapper.select:
SELECT COUNT(*) FROM app_agent_usage_ledger

    AND tenant_key = #{tenantKey}
    AND task_id = #{taskId}

SELECT id, task_id AS taskId, step_id AS stepId, tenant_key AS tenantKey,
       idempotency_key AS idempotencyKey, tool_name AS toolName, attempt,
       token_usage AS tokenUsage, cost_amount AS costAmount, status, created_at AS createdAt
FROM app_agent_usage_ledger

    AND tenant_key = #{tenantKey}
    AND task_id = #{taskId}

ORDER BY created_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM app_agent_task t
WHERE t.created_by = #{ownerId}
AND t.status = #{status}

    AND (
        t.task_key LIKE CONCAT('%', #{keyword}, '%')
        OR t.title LIKE CONCAT('%', #{keyword}, '%')
        OR t.objective LIKE CONCAT('%', #{keyword}, '%')
    )

SELECT t.id, t.task_key AS taskKey, t.task_type AS taskType, t.title, t.status, t.risk_level AS riskLevel, t.created_by AS createdBy, t.tenant_key AS tenantKey, t.priority, t.max_steps AS maxSteps, t.max_retries AS maxRetries, t.max_runtime_seconds AS maxRuntimeSeconds, t.max_tokens AS maxTokens, t.max_cost AS maxCost, t.current_step_id AS currentStepId, t.total_steps AS totalSteps, t.completed_steps AS completedSteps, t.retry_count AS retryCount, t.token_usage AS tokenUsage, t.cost_amount AS costAmount, t.artifact_count AS artifactCount, t.started_at AS startedAt, t.finished_at AS finishedAt, COALESCE(t.last_error, '') AS lastError, t.created_at AS createdAt, t.updated_at AS updatedAt FROM app_agent_task t WHERE t.created_by = #{ownerId} AND t.status = #{status}
AND ( t.task_key LIKE CONCAT('%', #{keyword}, '%') OR t.title LIKE CONCAT('%', #{keyword}, '%') OR t.objective LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY t.updated_at DESC, t.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT w.id, w.workflow_key AS workflowKey, w.version, w.display_name AS displayName, w.description, w.task_type AS taskType, w.steps_json AS stepsJson, w.allowed_roles_json AS allowedRolesJson, w.allowed_tools_json AS allowedToolsJson, w.max_steps AS maxSteps, w.max_runtime_seconds AS maxRuntimeSeconds, w.max_tokens AS maxTokens, w.max_cost AS maxCost, w.failure_policy AS failurePolicy, w.approval_required AS approvalRequired, w.enabled FROM app_agent_workflow_template w WHERE w.task_type = #{taskType} AND w.enabled = 1
AND w.workflow_key = #{workflowKey}
ORDER BY w.version DESC, w.id DESC LIMIT 1

SELECT COALESCE(MAX(version), 0) + 1
FROM app_agent_role_definition
WHERE role_key = #{roleKey}

