) VALUES (
    #{roleKey}, #{version}, #{displayName}, #{description}, #{systemPrompt},
    #{inputSchema}, #{outputSchema}, #{allowedToolsJson}, #{routeKey},
    #{maxTokens}, #{maxLoops}, #{riskLevel}, #{enabled}, #{createdBy}, #{updatedBy}
)

