mapper.insert:
INSERT INTO app_agent_config_audit (
    config_type, config_id, config_key, version, action, operator_id, summary
) VALUES (
    #{configType}, #{configId}, #{configKey}, #{version}, #{action}, #{operatorId}, #{summary}
)

mapper.select:
SELECT COUNT(*)
FROM app_agent_artifact a
INNER JOIN app_agent_task t ON t.id = a.task_id
WHERE a.artifact_key = 'agent-evaluation'
AND t.task_type = #{taskType}
AND t.tenant_key = #{tenantKey}
AND JSON_UNQUOTE(JSON_EXTRACT(a.content_json, '$.verdict')) = #{verdict}
AND CAST(JSON_UNQUOTE(JSON_EXTRACT(a.content_json, '$.score')) AS DECIMAL(10,2)) >= #{minimumScore}
AND JSON_UNQUOTE(JSON_EXTRACT(a.content_json, '$.evaluationGatePassed')) = CASE WHEN #{gatePassed} = TRUE THEN 'true' ELSE 'false' END

SELECT a.id AS artifactId, a.task_id AS taskId, t.task_key AS taskKey,
       t.task_type AS taskType, t.title, t.status AS taskStatus, t.tenant_key AS tenantKey,
       a.content_json AS contentJson, a.content_hash AS contentHash,
       a.created_at AS createdAt
FROM app_agent_artifact a
INNER JOIN app_agent_task t ON t.id = a.task_id
WHERE a.artifact_key = 'agent-evaluation'
AND t.task_type = #{taskType}
AND t.tenant_key = #{tenantKey}
AND JSON_UNQUOTE(JSON_EXTRACT(a.content_json, '$.verdict')) = #{verdict}
AND CAST(JSON_UNQUOTE(JSON_EXTRACT(a.content_json, '$.score')) AS DECIMAL(10,2)) >= #{minimumScore}
AND JSON_UNQUOTE(JSON_EXTRACT(a.content_json, '$.evaluationGatePassed')) = CASE WHEN #{gatePassed} = TRUE THEN 'true' ELSE 'false' END
ORDER BY a.created_at DESC, a.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM app_agent_tenant t

    AND t.status = #{status}
    AND (t.tenant_key LIKE CONCAT('%', #{keyword}, '%') OR t.display_name LIKE CONCAT('%', #{keyword}, '%'))

SELECT t.id, t.tenant_key AS tenantKey, t.display_name AS displayName, t.status, t.created_by AS createdBy, t.created_at AS createdAt, t.updated_at AS updatedAt, (SELECT COUNT(*) FROM app_agent_tenant_member m WHERE m.tenant_key = t.tenant_key AND m.status = 'ACTIVE') AS activeMemberCount FROM app_agent_tenant t
AND t.status = #{status} AND (t.tenant_key LIKE CONCAT('%', #{keyword}, '%') OR t.display_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY t.updated_at DESC, t.id DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE app_agent_tenant
SET status = #{status}, updated_by = #{updatedBy}, updated_at = CURRENT_TIMESTAMP
WHERE tenant_key = #{tenantKey}

mapper.select:
SELECT COUNT(*) FROM app_agent_tenant_member
WHERE tenant_key = #{tenantKey}
AND status = #{status}

SELECT id, tenant_key AS tenantKey, user_id AS userId, member_role AS memberRole,
       status, created_by AS createdBy, created_at AS createdAt, updated_at AS updatedAt
FROM app_agent_tenant_member
WHERE tenant_key = #{tenantKey}
AND status = #{status}
ORDER BY updated_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}
